[CommandMethod("PFCOUNT", CommandFlags.UsePickSet)]
public void PfCount() {
    var ed = Application.DocumentManager.MdiActiveDocument.Editor;
    var r = ed.SelectImplied();
    var ss = r.Status == PromptStatus.OK ? r.Value : ed.GetSelection().Value;
    if (ss != null) ed.WriteMessage($"\n{ss.Count} objects");
}

