[LispFunction("ADDNUMS")]
public ResultBuffer AddNums(ResultBuffer args) {
    double sum = 0;
    if (args != null)
        foreach (TypedValue tv in args)
            if (tv.TypeCode == (int)LispDataType.Double || tv.TypeCode == (int)LispDataType.Int16)
                sum += Convert.ToDouble(tv.Value);
    return new ResultBuffer(new TypedValue((int)LispDataType.Double, sum));
}

