void Db_ObjectAppended(object sender, ObjectEventArgs e) {
    var db = (Database)sender;
    using (var tr = db.TransactionManager.StartOpenCloseTransaction()) {
        var ent = tr.GetObject(e.DBObject.ObjectId, OpenMode.ForRead) as Entity;
        // inspect only; do not modify the notifying object here
        tr.Commit();
    }
}

